/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
def detect(fr):
    R,G,B = fr[...,0],fr[...,1],fr[...,2]
    mask = (G>120)&(R>100)&(B<120)&(G>R-20)&(R>B+40)
    ys,xs = np.where(mask)
    if len(xs)==0: return None
    return xs.mean(), ys.mean(), len(xs), xs.min(),xs.max(),ys.min(),ys.max()
for t in range(96):
    r = detect(d[t])
    if r: print(t, 'x=%.2f y=%.2f n=%d bb=(%d,%d,%d,%d)'%(r[0],r[1],r[2],r[3],r[4],r[5],r[6]))
    else: print(t,'NONE')
\""
